// Package node defines the document data model shared by every format
// decoder/encoder and the expression evaluator. It mirrors the shape of a
// YAML node tree: every JSON/XML/CSV/... document is decoded into this tree,
// and every encoder renders from it.
package node

// Kind identifies the structural kind of a Node.
type Kind int

const (
	DocumentKind Kind = 1 + iota
	SequenceKind
	MappingKind
	ScalarKind
	AliasKind
)

func (k Kind) String() string {
	switch k {
	case DocumentKind:
		return "Document"
	case SequenceKind:
		return "Sequence"
	case MappingKind:
		return "Mapping"
	case ScalarKind:
		return "Scalar"
	case AliasKind:
		return "Alias"
	}
	return "Unknown"
}

// Style is a bitmask of presentation styles (only meaningful for output).
type Style int

const (
	StyleDefault       Style = 0
	TaggedStyle        Style = 1 << 0
	DoubleQuotedStyle  Style = 1 << 1
	SingleQuotedStyle  Style = 1 << 2
	LiteralStyle       Style = 1 << 3
	FoldedStyle        Style = 1 << 4
	FlowStyle          Style = 1 << 5
)

func (s Style) IsFlow() bool          { return s&FlowStyle != 0 }
func (s Style) IsDoubleQuoted() bool  { return s&DoubleQuotedStyle != 0 }
func (s Style) IsSingleQuoted() bool  { return s&SingleQuotedStyle != 0 }
func (s Style) IsLiteral() bool       { return s&LiteralStyle != 0 }
func (s Style) IsFolded() bool        { return s&FoldedStyle != 0 }
func (s Style) IsTagged() bool        { return s&TaggedStyle != 0 }
func (s Style) IsQuoted() bool {
	return s&(DoubleQuotedStyle|SingleQuotedStyle) != 0
}

// Node is a single node in a document tree.
//
// For MappingKind, Content holds alternating key/value nodes
// (key at even indexes, value at odd indexes).
// For SequenceKind, Content holds the elements.
// For DocumentKind, Content holds exactly one root node (or zero for an
// empty document).
// For ScalarKind, Value holds the text and Tag the resolved YAML tag
// (e.g. "!!str", "!!int", "!!float", "!!bool", "!!null", "!!timestamp").
// For AliasKind, Alias points to the anchored node it refers to and Value
// holds the alias name.
type Node struct {
	Kind    Kind
	Style   Style
	Tag     string
	Value   string
	Anchor  string
	Alias   *Node
	Content []*Node

	HeadComment string
	LineComment string
	FootComment string
}

// NewScalar creates a scalar node with the given tag and value.
func NewScalar(tag, value string) *Node {
	return &Node{Kind: ScalarKind, Tag: tag, Value: value}
}

// NewString creates a !!str scalar.
func NewString(value string) *Node { return NewScalar("!!str", value) }

// NewNull creates a !!null scalar with value "null".
func NewNull() *Node { return NewScalar("!!null", "null") }

// NewMapping creates an empty !!map node.
func NewMapping() *Node { return &Node{Kind: MappingKind, Tag: "!!map"} }

// NewSequence creates an empty !!seq node.
func NewSequence() *Node { return &Node{Kind: SequenceKind, Tag: "!!seq"} }

// NewDocument wraps a root node in a document node.
func NewDocument(root *Node) *Node {
	d := &Node{Kind: DocumentKind}
	if root != nil {
		d.Content = []*Node{root}
	}
	return d
}

// Root returns the root content node of a document (nil if empty).
func (n *Node) Root() *Node {
	if n.Kind == DocumentKind {
		if len(n.Content) == 0 {
			return nil
		}
		return n.Content[0]
	}
	return n
}

// MapKeys returns the key nodes of a mapping.
func (n *Node) MapKeys() []*Node {
	keys := make([]*Node, 0, len(n.Content)/2)
	for i := 0; i+1 < len(n.Content); i += 2 {
		keys = append(keys, n.Content[i])
	}
	return keys
}

// MapValue returns the value node for a key in a mapping, or nil.
func (n *Node) MapValue(key string) *Node {
	if n.Kind == DocumentKind {
		return n.Root().MapValue(key)
	}
	if n == nil || n.Kind != MappingKind {
		return nil
	}
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == key {
			return n.Content[i+1]
		}
	}
	return nil
}

// MapSet sets (or appends) a key/value pair in a mapping.
func (n *Node) MapSet(key *Node, value *Node) {
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == key.Value {
			n.Content[i+1] = value
			return
		}
	}
	n.Content = append(n.Content, key, value)
}

// IsNull reports whether the node is a !!null scalar.
func (n *Node) IsNull() bool {
	return n != nil && n.Kind == ScalarKind && n.Tag == "!!null"
}

// Clone makes a deep copy of the node (alias targets are shared).
func (n *Node) Clone() *Node {
	if n == nil {
		return nil
	}
	c := *n
	if n.Content != nil {
		c.Content = make([]*Node, len(n.Content))
		for i, ch := range n.Content {
			c.Content[i] = ch.Clone()
		}
	}
	return &c
}

// AddFootComment appends a line to the foot comment.
func (n *Node) AddFootComment(s string) {
	if n.FootComment == "" {
		n.FootComment = s
	} else {
		n.FootComment = n.FootComment + "\n" + s
	}
}

// AddHeadComment appends a line to the head comment.
func (n *Node) AddHeadComment(s string) {
	if n.HeadComment == "" {
		n.HeadComment = s
	} else {
		n.HeadComment = n.HeadComment + "\n" + s
	}
}

// Package settings holds the global, flag-driven settings shared by all
// decoders, encoders and the evaluator. The CLI builds one Settings value
// from the command line and passes it everywhere.
package settings

// Settings aggregates every command-line flag of the tool.
type Settings struct {
	// General
	Colors       bool // -C --colors: force colors
	NoColors     bool // -M --no-colors: force no colors
	ExitStatus   bool // -e --exit-status
	InPlace      bool // -i --inplace
	Indent       int  // -I --indent (default 2)
	NullInput    bool // -n --null-input
	NoDoc        bool // -N --no-doc: don't print document separators
	NulOutput    bool // -0 --nul-output
	PrettyPrint  bool // -P --prettyPrint
	UnwrapScalar bool // -r --unwrapScalar (default true)
	Verbose      bool // -v --verbose

	// Formats: one of auto|yaml|kyaml|json|props|csv|tsv|xml|base64|uri|toml|hcl|lua|ini|shell
	InputFormat  string // -p --input-format (default "auto")
	OutputFormat string // -o --output-format (default "auto")

	// CSV/TSV
	CsvSeparator byte // --csv-separator (default ',')
	CsvAutoParse bool // --csv-auto-parse (default true)
	TsvAutoParse bool // --tsv-auto-parse (default true)

	// XML
	XmlAttributePrefix string // --xml-attribute-prefix (default "+@")
	XmlContentName     string // --xml-content-name (default "+content")
	XmlDirectiveName   string // --xml-directive-name (default "+directive")
	XmlProcInstPrefix  string // --xml-proc-inst-prefix (default "+p_")
	XmlKeepNamespace   bool   // --xml-keep-namespace (default true)
	XmlRawToken        bool   // --xml-raw-token (default true)
	XmlSkipDirectives  bool   // --xml-skip-directives
	XmlSkipProcInst    bool   // --xml-skip-proc-inst
	XmlStrictMode      bool   // --xml-strict-mode

	// Properties
	PropsSeparator     string // --properties-separator (default " = ")
	PropsArrayBrackets bool   // --properties-array-brackets

	// Lua
	LuaGlobals  bool   // --lua-globals
	LuaPrefix   string // --lua-prefix (default "return ")
	LuaSuffix   string // --lua-suffix (default ";\n")
	LuaUnquoted bool   // --lua-unquoted

	// Shell
	ShellKeySeparator string // --shell-key-separator (default "_")

	// Front matter: "" | "extract" | "process"
	FrontMatter string // -f --front-matter

	// Security
	SecurityDisableEnvOps        bool // --security-disable-env-ops
	SecurityDisableFileOps       bool // --security-disable-file-ops
	SecurityEnableSystemOperator bool // --security-enable-system-operator

	// Advanced
	Expression          string // --expression
	FromFile            string // --from-file
	HeaderPreprocess    bool   // --header-preprocess (default true)
	SplitExp            string // -s --split-exp
	SplitExpFile        string // --split-exp-file
	StringInterpolation bool   // --string-interpolation (default true)
	DebugNodeInfo       bool   // --debug-node-info

	// YAML output
	YamlCompactSeqIndent   bool // -c --yaml-compact-seq-indent
	YamlFixMergeAnchorSpec bool // --yaml-fix-merge-anchor-to-spec

	// EvalAll is true when running the eval-all command.
	EvalAll bool

	// ForceColor/NoColor resolved: call ColorsEnabled().
}

// New returns Settings with all defaults applied.
func New() *Settings {
	return &Settings{
		Indent:             2,
		UnwrapScalar:       true,
		InputFormat:        "auto",
		OutputFormat:       "auto",
		CsvSeparator:       ',',
		CsvAutoParse:       true,
		TsvAutoParse:       true,
		XmlAttributePrefix: "+@",
		XmlContentName:     "+content",
		XmlDirectiveName:   "+directive",
		XmlProcInstPrefix:  "+p_",
		XmlKeepNamespace:   true,
		XmlRawToken:        true,
		PropsSeparator:     " = ",
		LuaPrefix:          "return ",
		LuaSuffix:          ";\n",
		ShellKeySeparator:  "_",
		HeaderPreprocess:   true,
		StringInterpolation: true,
	}
}

// ColorsEnabled reports whether colored output should be produced,
// given whether stdout is a terminal.
func (s *Settings) ColorsEnabled(stdoutIsTTY bool) bool {
	if s.Colors {
		return true
	}
	if s.NoColors {
		return false
	}
	return stdoutIsTTY
}

// Package expr defines the abstract syntax tree for yq/jq-like expressions
// and the parser that produces it.
//
// The AST is pure data. The evaluator (package eval) walks it.
//
// Grammar sketch (jq-like, yq flavored), from loosest to tightest binding:
//
//	expr      := defSource
//	defSource := ("def" IDENT params? ":" expr ";")* pipeExpr
//	pipeExpr  := commaExpr ("|" commaExpr)*
//	commaExpr := assignExpr ("," assignExpr)*
//	assignExpr:= altExpr (ASSIGN_OP altExpr)?        // right associative
//	altExpr   := orExpr ("//" orExpr)*
//	orExpr    := andExpr ("or" andExpr)*
//	andExpr   := cmpExpr ("and" cmpExpr)*
//	cmpExpr   := addExpr (("=="|"!="|"<="|">="|"<"|">") addExpr)?
//	addExpr   := mulExpr (("+"|"-") mulExpr)*
//	mulExpr   := unary (("*"|"/"|"%") unary)*
//	unary     := "-" unary | postfix
//	postfix   := primary (pathSegment)*            // .a[0] chains, "?" suffix
//	primary   := "." | ".." | IDENT call? | STRING | NUMBER | "true" | "false"
//	           | "null" | "[" expr? "]" | "{" objEntries "}" | "(" expr ")"
//	           | VARIABLE | ifExpr | tryExpr | reduceExpr | "@"format
//	pathSegment := "." IDENT | "." STRING | "[" expr "]" | "[]" etc.
//
// ASSIGN_OP is one of: = |= += -= *= /= %= //=
package expr

// Kind enumerates AST node kinds.
type Kind int

const (
	KIdentity Kind = iota // "."
	KPipe                 // Args[0] | Args[1]
	KComma                // Args[0] , Args[1]
	KRecurse              // ".." (recursive descent)

	// KTraverseKey: .foo  ."foo"  .["foo"] — Str holds the key.
	// Optional is true for the ".foo?" form.
	KTraverseKey
	// KTraverseIndex: .[3] .[-1] — Str holds the raw integer text.
	KTraverseIndex
	// KTraverseSlice: .[a:b] — Args[0], Args[1] are expressions or nil.
	KTraverseSlice
	// KIterate: .[] — Optional is true for ".[]?".
	KIterate
	// KTraverseExpr: dynamic traversal .[expr] — Args[0] is the key/index expr.
	KTraverseExpr

	KCollect         // [ expr ] — Args[0], or zero Args for []
	KObjectConstruct // { entries } — Args are KObjectEntry nodes
	KObjectEntry     // Args[0]=key expr, Args[1]=value expr (nil for {a} shorthand)

	KLiteralNull
	KLiteralBool   // Str = "true" or "false"
	KLiteralNumber // Str = raw numeric text as written
	KLiteralString // Args = parts: KStringPart nodes and interpolated exprs
	KStringPart    // Str = literal text chunk of a string

	// KBinaryOp: Str is one of: + - * / % == != < <= > >= and or //
	KBinaryOp
	KUnaryMinus // Args[0]

	// KAssign: Str is the assignment operator: = |= += -= *= /= %= //=
	// Args[0] is the path expression, Args[1] the value expression.
	KAssign

	// KFuncCall: Str = function name (e.g. select, map, length, keys, has,
	// env, strenv, sort_by, ...). Args = parameters (e.g. select(cond) has
	// one arg; limit(2; x) has two). Zero-arg builtins have no Args.
	// A bare identifier like NAME inside env(NAME) parses as KFuncCall with
	// no Args; eval treats those as variable lookups where appropriate.
	KFuncCall

	KVariable // Str = variable name (without $)

	// KAs: Args[0] as $x | Args[2]. Args[1] is the KVariable.
	KAs
	// KReduce: reduce Args[0] as $x (Args[2]; Args[3]). Args[1]=KVariable.
	KReduce
	// KIf: if Args[0] then Args[1] else Args[2] end. Args[2] may be nil
	// (meaning identity). elif chains are nested KIf nodes.
	KIf
	// KTry: try Args[0] catch Args[1]; Args[1] nil when no catch clause.
	KTry

	// KFormat: @base64, @json, @base64d, ... Str = name without "@".
	KFormat

	// KDef: def f(params): body; rest
	// Args[0] = KFuncSignature, Args[1] = body, Args[2] = rest expression.
	KDef
	// KFuncSignature: Str = function name, Args = KVariable params.
	KFuncSignature
)

// Node is one AST node.
type Node struct {
	Kind     Kind
	Str      string
	Args     []*Node
	Optional bool
}

// Parse parses an expression source string into an AST.
// The returned error message must match the original tool's format:
//
//	1:7: lexer: invalid input text "..."
//
// or for parser errors:
//
//	Error: bad expression, please check expression syntax
//
// (See the original binary for exact messages by feeding it bad input.)
func Parse(src string) (*Node, error) {
	p := &parser{src: src}
	return p.parse()
}

